<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Autonomous Snake Game</title>
<style>
  body{margin:0;background:#111;display:flex;justify-content:center;align-items:center;height:100vh;color:#fff;font-family:Arial,Helvetica,sans-serif;}
  canvas{background:#000;border:2px solid #444;}
  #score{position:absolute;top:10px;left:10px;font-size:1.5em;}
</style>
</head>
<body>
<canvas id="game" width="400" height="400"></canvas>
<div id="score">Score: 0</div>
<script>
"use strict";
const canvas=document.getElementById('game'), ctx=canvas.getContext('2d');
const cellSize=20, gridSize=canvas.width/cellSize; // 20x20 grid
let snake=[{x:10,y:10}]; // start center
let direction={x:1,y:0};
let food=spawnFood();
let score=0;
let gameRunning=true;

// Draw everything
function draw(){
  ctx.fillStyle='#000'; ctx.fillRect(0,0,canvas.width,canvas.height);
  // draw food
  ctx.fillStyle='#f00'; ctx.fillRect(food.x*cellSize,food.y*cellSize,cellSize,cellSize);
  // draw snake
  ctx.fillStyle='#0f0';
  snake.forEach((segment,i)=>{ctx.fillRect(segment.x*cellSize,segment.y*cellSize,cellSize,cellSize);});
}

// AI: choose next direction
function chooseDirection(){
  const moves=[
    {x:0,y:-1}, // up
    {x:1,y:0},  // right
    {x:0,y:1},  // down
    {x:-1,y:0}  // left
  ];
  const currentHead=snake[0];
  let bestMove=null, bestDist=Infinity;
  for(const mv of moves){
    const nx=currentHead.x+mv.x, ny=currentHead.y+mv.y;
    if(nx<0||nx>=gridSize||ny<0||ny>=gridSize) continue; // wall
    if(isCollision(nx,ny)) continue; // body
    const dist=Math.abs(nx-food.x)+Math.abs(ny-food.y);
    if(dist<bestDist){
      bestDist=dist; bestMove=mv;
    }
  }
  // If no safe move, try any that doesn't collide
  if(!bestMove){
    for(const mv of moves){
      const nx=currentHead.x+mv.x, ny=currentHead.y+mv.y;
      if(nx<0||nx>=gridSize||ny<0||ny>=gridSize) continue;
      if(isCollision(nx,ny)) continue;
      bestMove=mv; break;
    }
  }
  return bestMove || {x:0,y:0};
}

// Check if new head would collide with snake body
function isCollision(x,y){
  return snake.some(seg=>seg.x===x&&seg.y===y);
}

// Spawn food not on snake
function spawnFood(){
  let fx,fy;
  do{
    fx=Math.floor(Math.random()*gridSize);
    fy=Math.floor(Math.random()*gridSize);
  }while(isCollision(fx,fy));
  return {x:fx,y:fy};
}

// Move snake
function move(){
  if(!gameRunning) return;
  const nextDir=chooseDirection();
  const newHead={x:snake[0].x+nextDir.x, y:snake[0].y+nextDir.y};

  // Check collision with walls or self
  if(newHead.x<0||newHead.x>=gridSize||newHead.y<0||newHead.y>=gridSize||isCollision(newHead.x,newHead.y)){
    gameRunning=false; alert('Game Over! Final Score: '+score); return;
  }

  // Add new head
  snake.unshift(newHead);

  // Check if food eaten
  if(newHead.x===food.x && newHead.y===food.y){
    score++; document.getElementById('score').textContent='Score: '+score;
    food=spawnFood();
  }else{
    snake.pop(); // remove tail
  }

  draw();
}

// Game loop
setInterval(move,150);
draw();
</script>
</body>
</html>
```
